// LittleCMS applies the supplied ICC; no profile name or format guess is used.
#include "lcms2_internal.h"
#include <lcms2_plugin.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdarg.h>
typedef struct {cmsContext context;cmsHTRANSFORM transform;} ColorTransform;
static char last_error[256];
static void error_handler(cmsContext context,cmsUInt32Number code,const char *message){(void)context;snprintf(last_error,sizeof(last_error),"LittleCMS %u: %s",code,message?message:"unknown color error");}
const char *color_native_error(void){return last_error;}
unsigned color_native_version(void){return LCMS_VERSION;}
uintptr_t color_native_create(const unsigned char *profile,unsigned length,unsigned input,unsigned output,unsigned intent,unsigned black_point){
 last_error[0]=0;if(!profile||length<128||input<1||input>6||output<1||output>3||intent>3){snprintf(last_error,sizeof(last_error),"Invalid color transform contract");return 0;}
 ColorTransform *owner=calloc(1,sizeof(*owner));if(!owner)return 0;owner->context=cmsCreateContext(NULL,NULL);if(!owner->context){free(owner);return 0;}cmsSetLogErrorHandlerTHR(owner->context,error_handler);
 cmsHPROFILE source=cmsOpenProfileFromMemTHR(owner->context,profile,length),destination=output==3?cmsCreateXYZProfileTHR(owner->context):cmsCreate_sRGBProfileTHR(owner->context);const unsigned layout=(input-1)%3;cmsColorSpaceSignature expected=layout==0?cmsSigRgbData:layout==1?cmsSigCmykData:cmsSigGrayData;
 const unsigned input_formats[6]={TYPE_RGB_16,TYPE_CMYK_16,TYPE_GRAY_16,TYPE_RGB_FLT,TYPE_CMYK_FLT,TYPE_GRAY_FLT};
 if(source&&cmsGetColorSpace(source)!=expected){snprintf(last_error,sizeof(last_error),"ICC channel space differs from the declared sample format");cmsCloseProfile(source);source=NULL;}
 if(source&&destination)owner->transform=cmsCreateTransformTHR(owner->context,source,input_formats[input-1],destination,output==1?TYPE_RGB_16:output==2?TYPE_RGB_8:TYPE_XYZ_FLT,intent,black_point?cmsFLAGS_BLACKPOINTCOMPENSATION:0);
 if(source)cmsCloseProfile(source);if(destination)cmsCloseProfile(destination);if(!owner->transform){cmsDeleteContext(owner->context);free(owner);return 0;}return(uintptr_t)owner;
}
void color_native_convert(uintptr_t handle,const void *input,void *output,unsigned pixels){ColorTransform *owner=(ColorTransform*)handle;if(owner&&owner->transform&&input&&output&&pixels)cmsDoTransform(owner->transform,input,output,pixels);}
void color_native_delete(uintptr_t handle){ColorTransform *owner=(ColorTransform*)handle;if(!owner)return;if(owner->transform)cmsDeleteTransform(owner->transform);cmsDeleteContext(owner->context);free(owner);}
unsigned color_native_srgb_profile(unsigned char *out,unsigned capacity){cmsHPROFILE profile=cmsCreate_sRGBProfile();cmsUInt32Number size=0;if(!profile)return 0;cmsSaveProfileToMem(profile,NULL,&size);if(out&&capacity>=size)cmsSaveProfileToMem(profile,out,&size);cmsCloseProfile(profile);return size;}
unsigned color_native_xyz_profile(unsigned char *out,unsigned capacity){cmsHPROFILE profile=cmsCreateXYZProfile();cmsUInt32Number size=0;if(!profile)return 0;cmsSaveProfileToMem(profile,NULL,&size);if(out&&capacity>=size)cmsSaveProfileToMem(profile,out,&size);cmsCloseProfile(profile);return size;}
static char profile_metadata[2048];
static unsigned append_xyz(unsigned at,const char *name,const cmsCIEXYZ *xyz){if(!xyz)return at;return at+(unsigned)snprintf(profile_metadata+at,sizeof(profile_metadata)-at,",\"%s\":[%.17g,%.17g,%.17g]",name,xyz->X,xyz->Y,xyz->Z);}
const char *color_native_profile_metadata(const unsigned char *bytes,unsigned length){cmsHPROFILE profile=cmsOpenProfileFromMem(bytes,length);if(!profile){strcpy(profile_metadata,"{}");return profile_metadata;}cmsColorSpaceSignature space=cmsGetColorSpace(profile),pcs=cmsGetPCS(profile);unsigned at=(unsigned)snprintf(profile_metadata,sizeof(profile_metadata),"{\"matrixShaper\":%s,\"colorSpace\":\"%c%c%c%c\",\"pcs\":\"%c%c%c%c\"",cmsIsMatrixShaper(profile)?"true":"false",space>>24,(space>>16)&255,(space>>8)&255,space&255,pcs>>24,(pcs>>16)&255,(pcs>>8)&255,pcs&255);at=append_xyz(at,"rXYZ",cmsReadTag(profile,cmsSigRedColorantTag));at=append_xyz(at,"gXYZ",cmsReadTag(profile,cmsSigGreenColorantTag));at=append_xyz(at,"bXYZ",cmsReadTag(profile,cmsSigBlueColorantTag));at=append_xyz(at,"wtpt",cmsReadTag(profile,cmsSigMediaWhitePointTag));const cmsMAT3 *chad=cmsReadTag(profile,cmsSigChromaticAdaptationTag);if(chad)at+=(unsigned)snprintf(profile_metadata+at,sizeof(profile_metadata)-at,",\"chad\":[[%.17g,%.17g,%.17g],[%.17g,%.17g,%.17g],[%.17g,%.17g,%.17g]]",chad->v[0].n[0],chad->v[0].n[1],chad->v[0].n[2],chad->v[1].n[0],chad->v[1].n[1],chad->v[1].n[2],chad->v[2].n[0],chad->v[2].n[1],chad->v[2].n[2]);snprintf(profile_metadata+at,sizeof(profile_metadata)-at,"}");cmsCloseProfile(profile);return profile_metadata;}
int color_native_profile_trc(const unsigned char *bytes,unsigned length,unsigned count,float *out){if(!out||count<2||count>65536)return 0;cmsHPROFILE profile=cmsOpenProfileFromMem(bytes,length);if(!profile)return 0;cmsToneCurve *curves[3]={cmsReadTag(profile,cmsSigRedTRCTag),cmsReadTag(profile,cmsSigGreenTRCTag),cmsReadTag(profile,cmsSigBlueTRCTag)};int ok=cmsIsMatrixShaper(profile)&&curves[0]&&curves[1]&&curves[2];if(ok)for(unsigned c=0;c<3;c++)for(unsigned i=0;i<count;i++)out[c*count+i]=cmsEvalToneCurveFloat(curves[c],(float)i/(float)(count-1));cmsCloseProfile(profile);return ok;}
unsigned color_native_rgb_profile(const double *xy,double gamma,unsigned char *out,unsigned capacity){if(!xy||gamma<=0||gamma>16)return 0;cmsCIExyY white={xy[0],xy[1],1};cmsCIExyYTRIPLE p={{xy[2],xy[3],1},{xy[4],xy[5],1},{xy[6],xy[7],1}};cmsToneCurve *curve=cmsBuildGamma(NULL,gamma);if(!curve)return 0;cmsToneCurve *curves[3]={curve,curve,curve};cmsHPROFILE profile=cmsCreateRGBProfile(&white,&p,curves);cmsFreeToneCurve(curve);if(!profile)return 0;cmsUInt32Number size=0;cmsSaveProfileToMem(profile,NULL,&size);if(out&&capacity>=size)cmsSaveProfileToMem(profile,out,&size);cmsCloseProfile(profile);return size;}
// Only nominal SDR/linear transfer functions. PQ and HLG require an explicit
// HDR display transform and must never be silently interpreted as sRGB gamma.
unsigned color_native_nominal_profile(unsigned primary,unsigned transfer,unsigned char *out,unsigned capacity){
 cmsCIExyY white={0.3127,0.3290,1};cmsCIExyYTRIPLE p;cmsToneCurve *curve=NULL;
 if(primary==1)p=(cmsCIExyYTRIPLE){{.64,.33,1},{.30,.60,1},{.15,.06,1}};else if(primary==9)p=(cmsCIExyYTRIPLE){{.708,.292,1},{.170,.797,1},{.131,.046,1}};else if(primary==12||primary==11){p=(cmsCIExyYTRIPLE){{.68,.32,1},{.265,.69,1},{.15,.06,1}};if(primary==11)white=(cmsCIExyY){.314,.351,1};}else return 0;
 if(transfer==8)curve=cmsBuildGamma(NULL,1);else if(transfer==4)curve=cmsBuildGamma(NULL,2.2);else if(transfer==5)curve=cmsBuildGamma(NULL,2.8);else if(transfer==13){cmsFloat64Number a[5]={2.4,1/1.055,.055/1.055,1/12.92,.04045};curve=cmsBuildParametricToneCurve(NULL,4,a);}else if(transfer==1||transfer==14||transfer==15){double alpha=transfer==15?1.0993:1.099,beta=transfer==15?.0181:.018;cmsFloat64Number a[5]={1/.45,1/alpha,(alpha-1)/alpha,1/4.5,4.5*beta};curve=cmsBuildParametricToneCurve(NULL,4,a);}else return 0;
 if(!curve)return 0;cmsToneCurve *curves[3]={curve,curve,curve};cmsHPROFILE profile=cmsCreateRGBProfile(&white,&p,curves);cmsFreeToneCurve(curve);if(!profile)return 0;cmsUInt32Number size=0;cmsSaveProfileToMem(profile,NULL,&size);if(out&&capacity>=size)cmsSaveProfileToMem(profile,out,&size);cmsCloseProfile(profile);return size;
}

// Read-only, version-pinned inspection of the transform actually used by LCMS.
// Do not reconstruct a profile matrix in place of an optimized integer CLUT.
static char pipeline_metadata[8192];static unsigned pipeline_at;static int pipeline_overflow;
static void pipeline_text(const char *format,...){if(pipeline_overflow)return;va_list args;va_start(args,format);int n=vsnprintf(pipeline_metadata+pipeline_at,sizeof(pipeline_metadata)-pipeline_at,format,args);va_end(args);if(n<0||(unsigned)n>=sizeof(pipeline_metadata)-pipeline_at){pipeline_overflow=1;return;}pipeline_at+=(unsigned)n;}
static cmsPipeline *display_pipeline(uintptr_t handle){ColorTransform*owner=(ColorTransform*)handle;if(!owner||!owner->transform)return NULL;_cmsTRANSFORM*t=(_cmsTRANSFORM*)owner->transform;if(t->InputFormat!=TYPE_RGB_16||t->OutputFormat!=TYPE_RGB_8||!t->Lut||cmsPipelineInputChannels(t->Lut)!=3||cmsPipelineOutputChannels(t->Lut)!=3)return NULL;return t->Lut;}
static cmsStage *display_stage(uintptr_t handle,unsigned index){cmsPipeline*p=display_pipeline(handle);if(!p)return NULL;cmsStage*s=cmsPipelineGetPtrToFirstStage(p);while(s&&index--){s=cmsStageNext(s);}return s;}
const char *color_native_pipeline_metadata(uintptr_t handle){cmsPipeline*p=display_pipeline(handle);pipeline_at=0;pipeline_overflow=0;pipeline_metadata[0]=0;if(!p||cmsPipelineStageCount(p)>8)return "{\"eligible\":false}";_cmsTRANSFORM*t=(_cmsTRANSFORM*)((ColorTransform*)handle)->transform;const int floating=p->Data==p;int eligible=1;unsigned index=0,cluts=0;pipeline_text("{\"library\":%u,\"inputFormat\":%u,\"outputFormat\":%u,\"flags\":%u,\"inputChannels\":3,\"outputChannels\":3,\"evaluationMode\":\"%s\",\"stages\":[",LCMS_VERSION,t->InputFormat,t->OutputFormat,t->dwOriginalFlags,floating?"float-stages":"optimized-integer");
 for(cmsStage*s=cmsPipelineGetPtrToFirstStage(p);s;s=cmsStageNext(s),index++){if(index)pipeline_text(",");cmsStageSignature kind=cmsStageType(s);if(kind==cmsSigCurveSetElemType){_cmsStageToneCurvesData*d=cmsStageData(s);if(d->nCurves!=3)return "{\"eligible\":false}";pipeline_text("{\"kind\":\"curves16\",\"values\":196608,\"precision\":%u,\"parametricTypes\":[%d,%d,%d],\"parametricParameters\":[",floating?32:16,cmsGetToneCurveParametricType(d->TheCurves[0]),cmsGetToneCurveParametricType(d->TheCurves[1]),cmsGetToneCurveParametricType(d->TheCurves[2]));for(unsigned c=0;c<3;c++){if(c)pipeline_text(",");pipeline_text("[");int type=cmsGetToneCurveParametricType(d->TheCurves[c]);const cmsCurveSegment*segment=cmsGetToneCurveSegment(0,d->TheCurves[c]);unsigned n=abs(type)==4?5:abs(type)==1?1:0;if(!segment)n=0;for(unsigned j=0;j<n;j++)pipeline_text("%s%.17g",j?",":"",segment->Params[j]);pipeline_text("]");}pipeline_text("]}");}
 else if(kind==cmsSigCLutElemType){_cmsStageCLutData*d=cmsStageData(s);cmsInterpParams*q=d->Params;if(floating||d->HasFloatValues||q->nInputs!=3||q->nOutputs!=3||q->dwFlags!=0)return "{\"eligible\":false}";cluts++;pipeline_text("{\"kind\":\"tetrahedral16\",\"values\":%u,\"precision\":16,\"grid\":[%u,%u,%u],\"flags\":%u}",d->nEntries,q->nSamples[0],q->nSamples[1],q->nSamples[2],q->dwFlags);}
 else if(kind==cmsSigMatrixElemType){if(!floating||cmsStageInputChannels(s)!=3||cmsStageOutputChannels(s)!=3)return "{\"eligible\":false}";_cmsStageMatrixData*d=cmsStageData(s);pipeline_text("{\"kind\":\"matrix\",\"coefficients\":[");for(unsigned i=0;i<9;i++)pipeline_text("%s%.17g",i?",":"",d->Double[i]);pipeline_text("],\"offset\":[");for(unsigned i=0;i<3;i++)pipeline_text("%s%.17g",i?",":"",d->Offset?d->Offset[i]:0.0);pipeline_text("]}");}
 else {eligible=0;pipeline_text("{\"kind\":\"unsupported\"}");}}
 if(cluts>1)eligible=0;pipeline_text("],\"eligible\":%s}",eligible?"true":"false");return pipeline_overflow?"{\"eligible\":false}":pipeline_metadata;
}
unsigned color_native_pipeline_stage_size(uintptr_t handle,unsigned index){cmsPipeline*p=display_pipeline(handle);cmsStage*s=display_stage(handle,index);if(!p||!s)return 0;if(cmsStageType(s)==cmsSigCurveSetElemType){_cmsStageToneCurvesData*d=cmsStageData(s);return d->nCurves==3?3*65536*(p->Data==p?4:2):0;}if(cmsStageType(s)==cmsSigCLutElemType){_cmsStageCLutData*d=cmsStageData(s);if(d->HasFloatValues||d->nEntries>0x7fffffffu)return 0;return d->nEntries*2;}return 0;}
unsigned color_native_pipeline_stage_copy(uintptr_t handle,unsigned index,void*out,unsigned capacity){cmsPipeline*p=display_pipeline(handle);cmsStage*s=display_stage(handle,index);unsigned size=color_native_pipeline_stage_size(handle,index);if(!p||!s||!out||!size||capacity<size)return 0;if(cmsStageType(s)==cmsSigCLutElemType){_cmsStageCLutData*d=cmsStageData(s);memcpy(out,d->Tab.T,size);}else if(cmsStageType(s)==cmsSigCurveSetElemType){_cmsStageToneCurvesData*d=cmsStageData(s);if(p->Data==p){float*values=out;for(unsigned c=0;c<3;c++)for(unsigned i=0;i<65536;i++)values[c*65536+i]=cmsEvalToneCurveFloat(d->TheCurves[c],(float)((double)i/65535.0));}else{cmsUInt16Number*values=out;for(unsigned c=0;c<3;c++)for(unsigned i=0;i<65536;i++)values[c*65536+i]=cmsEvalToneCurve16(d->TheCurves[c],i);}}else return 0;return size;}
